insert into public.academy_missions(id,version,config,published) values
('corredor',1,$mission${"id":"corredor","title":"Inspeção de corredor linear","scene":"survey","brief":"Simule a inspeção de uma faixa de infraestrutura. Decole em Cine, percorra quatro setores a 20 m mantendo velocidade controlada e retorne à base. Em cada setor, estabilize por 4 s antes de continuar. Os marcadores indicam a posição da aeronave.","goals":[{"kind":"mode","label":"Selecionar Cine para inspeção","value":"Cine","seconds":3},{"kind":"point","label":"Inspecionar setor sul","x":0,"z":-25,"h":20,"radius":6,"tolerance":4,"seconds":4},{"kind":"point","label":"Inspecionar setor central","x":0,"z":-55,"h":20,"radius":6,"tolerance":4,"seconds":4},{"kind":"point","label":"Inspecionar setor norte","x":0,"z":-85,"h":20,"radius":6,"tolerance":4,"seconds":4},{"kind":"point","label":"Conferir margem leste","x":25,"z":-55,"h":20,"radius":6,"tolerance":4,"seconds":4},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":11,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true),
('documentacao',1,$mission${"id":"documentacao","title":"Documentação aérea de terreno","scene":"field","brief":"Produza um registro de um terreno para planejamento. Estabilize no ponto de observação, fotografe dois marcos no solo e grave uma tomada em Cine por 10 s. Ajuste o gimbal para enquadrar os alvos, pare a gravação e pouse na base.","goals":[{"kind":"point","label":"Estabilizar no ponto de observação","x":0,"z":-20,"h":25,"radius":6,"tolerance":4,"seconds":5},{"kind":"photo","label":"Fotografar marco oeste","x":-20,"z":-50,"h":1,"radius":65,"seconds":0},{"kind":"photo","label":"Fotografar marco leste","x":20,"z":-50,"h":1,"radius":65,"seconds":0},{"kind":"video","label":"Gravar panorama em Cine por 10 s","value":"Cine","seconds":10},{"kind":"land","label":"Pousar na base H sem colisão","radius":12,"seconds":1}],"order":12,"version":1,"maxScore":100,"maxDuration":1800,"maxHeight":100,"maxDistance":400,"initial":{"mode":"Normal","rthH":50,"maxH":100,"maxD":400},"zones":[],"quiz":{"question":"Qual condição exige interromper a operação?","choices":["Área isolada e origem confirmada","Pessoas entrando na área de operação","Bateria conferida e rota revisada"],"answer":1}}$mission$::jsonb,true);
